@Service
class OrderService(
    private val orders: OrderRepository,
    private val stock: StockGateway,
) {
    @Transactional                       // kotlin-spring opens the class for the proxy
    fun place(req: OrderRequest): OrderId {
        val order = orders.insert(Order.create(req))
        stock.reserve(order.id)
        return order.id
    }
}
